// PLANTILLA de scifi: sustituye este marcador por tu escena 3D.
// Gestos: browRaise, eyesWide. Sonido: window.folio.sfx.play("scifi")
var k = 0;
function init() { this.scale.setScalar(1); }
function browRaise() { k = 1; window.folio?.sfx.play("scifi"); }
function eyesWide() { k = 1; window.folio?.sfx.play("pop"); }
function update(event) { k = Math.max(0, k - event.delta / 700); this.scale.setScalar(1 + k * 1.5); this.rotation.y += event.delta / 800; }
